/* The symbol versions libamdhip64 defines, as ROCm 7.1's own library defines them.
 *
 * A program built by hipcc binds each HIP call to a version as well as a name --
 * hipMalloc@hip_4.2, hipGetDevicePropertiesR0600@hip_6.0 -- and the loader refuses
 * a library that defines the name under any other. So each function here sits in
 * the version the real library gives it. The whole chain of versions is declared
 * even where no function here belongs to one, so a program asking for any of them
 * finds it. Everything that is not HIP's own API stays local to the library.
 *
 * Regenerate with amd/tools/hip-version-script.py when a function is added. */

hip_4.2 {
  global:
    __hipPopCallConfiguration;
    __hipPushCallConfiguration;
    __hipRegisterFatBinary;
    __hipRegisterFunction;
    __hipRegisterVar;
    __hipUnregisterFatBinary;
    hipDeviceCanAccessPeer;
    hipDeviceDisablePeerAccess;
    hipDeviceEnablePeerAccess;
    hipDeviceGet;
    hipDeviceGetAttribute;
    hipDeviceGetName;
    hipDeviceReset;
    hipDeviceSynchronize;
    hipDeviceTotalMem;
    hipDriverGetVersion;
    hipEventCreate;
    hipEventCreateWithFlags;
    hipEventDestroy;
    hipEventElapsedTime;
    hipEventQuery;
    hipEventRecord;
    hipEventSynchronize;
    hipExtModuleLaunchKernel;
    hipFree;
    hipGetDevice;
    hipGetDeviceCount;
    hipGetDeviceProperties;
    hipGetErrorName;
    hipGetErrorString;
    hipGetLastError;
    hipGetStreamDeviceId;
    hipGetSymbolAddress;
    hipGetSymbolSize;
    hipHostFree;
    hipHostMalloc;
    hipInit;
    hipLaunchCooperativeKernel;
    hipLaunchKernel;
    hipMalloc;
    hipMemGetInfo;
    hipMemcpy;
    hipMemcpy2D;
    hipMemcpy2DAsync;
    hipMemcpyAsync;
    hipMemcpyFromSymbol;
    hipMemcpyFromSymbolAsync;
    hipMemcpyPeerAsync;
    hipMemcpyToSymbol;
    hipMemcpyToSymbolAsync;
    hipMemset;
    hipMemsetAsync;
    hipModuleGetFunction;
    hipModuleGetGlobal;
    hipModuleLaunchKernel;
    hipModuleLoad;
    hipModuleLoadData;
    hipModuleOccupancyMaxActiveBlocksPerMultiprocessor;
    hipModuleOccupancyMaxPotentialBlockSize;
    hipModuleUnload;
    hipOccupancyMaxActiveBlocksPerMultiprocessor;
    hipOccupancyMaxActiveBlocksPerMultiprocessorWithFlags;
    hipOccupancyMaxPotentialBlockSize;
    hipPeekAtLastError;
    hipPointerGetAttributes;
    hipRuntimeGetVersion;
    hipSetDevice;
    hipSetDeviceFlags;
    hipStreamCreate;
    hipStreamCreateWithFlags;
    hipStreamDestroy;
    hipStreamQuery;
    hipStreamSynchronize;
  local: *;
};
hip_4.3 {
  global:
    hipGraphDestroy;
    hipGraphExecDestroy;
    hipGraphInstantiate;
    hipGraphLaunch;
    hipStreamBeginCapture;
    hipStreamEndCapture;
    hipStreamIsCapturing;
} hip_4.2;
